$ui-pane-border: #D9D9D9;
$ui-pane-gray: #F9F9F9;
$ui-background-blue: #e8edf1;

$text-primary: #575e75;

$looks-secondary: #855CD6;
$looks-transparent: hsla(260, 60%, 60%, 0.35); /* 35% transparent version of looks-secondary */

$red-primary: #FF661A;
$red-tertiary: #E64D00;

$sound-primary: #CF63CF;
$sound-tertiary: #A63FA6;

$control-primary: #FFAB19;

$data-primary: #FF8C1A;

$form-border: #E9EEF2;
/* DO NOT EDIT
@todo This file is copied from GUI and should be pulled out into a shared library.
See https://github.com/LLK/scratch-paint/issues/13 */

/* ACTUALLY, THIS IS EDITED ;)
THIS WAS CHANGED ON 10/25/2017 BY @mewtaylor TO ADD A VARIABLE FOR THE SMALLEST
GRID UNITS.

ALSO EDITED ON 11/13/2017 TO ADD IN CONTANTS FOR LAYOUT FROM `layout-contents.js`*/

$space: 0.5rem;
$grid-unit: .25rem;

$sprites-per-row: 5;

$menu-bar-height: 3rem;
$sprite-info-height: 6rem;
$stage-menu-height: 2.75rem;

$library-header-height: 4.375rem;

$form-radius: calc($space / 2);

/* layout contants from `layout-constants.js`, minus 1px */
$full-size: 1095px;
$full-size-paint: 1256px;
@import '../../css/colors.css';
@import "../../css/units.css";

$border-radius: .25rem;

.mod-tool-select {
    display: inline-block;
    margin: $grid-unit;
    border: none;
    border-radius: $border-radius;
    outline: none;
    background: none;
    padding: $grid-unit;
    font-size: 0.85rem;
    transition: 0.2s;
}

.mod-tool-select.is-selected {
    background-color: $looks-secondary;
}

.mod-tool-select:focus {
    outline: none;
}

img.tool-select-icon {
    width: 2rem;
    height: 2rem;
    flex-grow: 1;
    vertical-align: middle;
}

.mod-tool-select.is-selected .tool-select-icon {
    /* Make the tool icons white while selected by making them black and inverting */
    filter: brightness(0) invert(1);
}

@media only screen and (max-width: $full-size-paint) {
    .mod-tool-select {
        margin: 0;
    }
}
